    if (getaddrinfo(NULL, port, &hints, &res) != 0) return;
    int fd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (fd >= 0) {
        bind(fd, res->ai_addr, res->ai_addrlen);
        listen(fd, 5);
    }
    freeaddrinfo(res);
}

int is_palindrome(const char *s) {
    int i = 0, j = strlen(s) - 1;
    while (i < j)
        if (s[i++] != s[j--]) return 0;
    return 1;
}

