struct Node {
    int key;
    struct Node *left, *right;
};

struct Node *insert(struct Node *n, int k) {
    if (!n) {
        n = malloc(sizeof(*n));
        n->key = k; n->left = n->right = NULL;
        return n;
    }
    if (k < n->key) n->left = insert(n->left, k);
    else if (k > n->key) n->right = insert(n->right, k);
    return n;
}

void inorder(struct Node *n) {
    if (!n) return;
    inorder(n->left);
    printf("%d ", n->key);
    inorder(n->right);
}

