void split(const char *s, char delim) {
    char buf[128];
    int b = 0;
    for (; *s; s++) {
        if (*s == delim) {
            buf[b] = '\0';
            if (b) printf("[%s]\n", buf);
            b = 0;
        } else {
            buf[b++] = *s;
        }
    }
    buf[b] = '\0';
    if (b) printf("[%s]\n", buf);
}

