}

void threaded_listener(int port) {
    srv_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (srv_fd < 0) return;
    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(port);
    if (bind(srv_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) return;
    listen(srv_fd, 5);
    pthread_t th;
    pthread_create(&th, NULL, accept_loop, NULL);
    pthread_detach(th);
}

int kmp_search(const char *text, const char *pat) {
    int n = strlen(text), m = strlen(pat);
    int lps[32] = {0};
    int len = 0, i = 1;
    while (i < m) {
        if (pat[i] == pat[len]) lps[i++] = ++len;
        else if (len) len = lps[len - 1];
        else lps[i++] = 0;
    }
    i = 0;
    int j = 0;
    while (i < n) {
        if (pat[j] == text[i]) { i++; j++; }
        if (j == m) return i - j;
        else if (i < n && pat[j] != text[i]) {
            if (j) j = lps[j - 1];
            else i++;
        }
    }
    return -1;
}

int main() {
    threaded_listener(8110);
    const char *txt = "ABABDABACDABABCABAB";
    const char *pat = "ABABCABAB";
    printf("found at: %d\n", kmp_search(txt, pat));
    return 0;
}
